// Block (composition) — a responsive grid of customer testimonial cards.
// Grid/Stack own arrangement; Card owns surfaces, Avatar owns identity look, and this Block owns quote content.
import type { Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Card } from "../components/Card";
import { Grid } from "../layouts/Grid";
import type { Responsive } from "../layouts/responsive";
import { Stack } from "../layouts/Stack";
import "./TestimonialGrid.css";

export interface TestimonialGridProps {
  testimonials: {
    quote: string;
    name: string;
    role?: string;
    avatarSrc?: string;
  }[];
  columns?: Responsive<number>;
  className?: string;
  ref?: Ref<HTMLElement>;
}

// The Avatar's fallback: `Avatar` derives nothing from `alt`, so an avatar with no `src` and no
// children renders an empty circle. Same helper as its peers (`ProfileCard`, `ReviewList`,
// `TeamGrid`), duplicated per Block on purpose — §7 copy-friendly.
function initials(name: string) {
  return name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

export function TestimonialGrid({
  testimonials,
  columns = { small: 1, medium: 3 },
  className,
  ref,
}: TestimonialGridProps) {
  return (
    <Grid
      as="section"
      ref={ref}
      aria-label="Customer testimonials"
      columns={columns}
      gap="medium"
      className={className ? `sd-testimonialgrid ${className}` : "sd-testimonialgrid"}
    >
      {testimonials.map((testimonial, index) => (
        <Card key={`${testimonial.name}-${index}`}>
          <Stack gap="small" className="sd-testimonialgrid__content">
            <>
              <blockquote className="sd-testimonialgrid__quote sd-type-body-medium">
                {testimonial.quote}
              </blockquote>
            </>
            <Stack direction="row" align="center" gap="small" className="sd-testimonialgrid__author">
              <Avatar src={testimonial.avatarSrc} size="small" alt={testimonial.name}>
                {initials(testimonial.name)}
              </Avatar>
              <Stack gap="2x-small" className="sd-testimonialgrid__identity">
                <div className="sd-testimonialgrid__name sd-type-body-medium">
                  {testimonial.name}
                </div>
                {testimonial.role && (
                  <div className="sd-testimonialgrid__role sd-type-caption-medium">
                    {testimonial.role}
                  </div>
                )}
              </Stack>
            </Stack>
          </Stack>
        </Card>
      ))}
    </Grid>
  );
}
